{
  "issues": [
    {
      "issue_id": "SPA-N-001",
      "position": "PUSHBACK",
      "evidence": "Seek a materially higher general warranty cap"
    },
    {
      "issue_id": "SPA-N-002",
      "position": "PUSHBACK",
      "evidence": "Lower the de minimis and basket; if a basket remains, seek a **tipping** basket."
    },
    {
      "issue_id": "SPA-N-003",
      "position": "PUSHBACK",
      "evidence": "Extend general warranty claims to at least 24 months"
    },
    {
      "issue_id": "SPA-N-004",
      "position": "PUSHBACK",
      "evidence": "Provide longer periods for title/fundamental claims."
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "Limit negotiated warranty limitations to warranty claims. Preserve claims for fraud, deliberate concealment, specific indemnities, covenants and price adjustments"
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "Reject deemed disclosure of the entire data room, public records, or matters merely discoverable."
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "Limit any knowledge qualifier to actual knowledge of named Buyer individuals, with no constructive, imputed or adviser knowledge."
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "No deemed satisfaction merely on delivery of a document; include a long-stop date and Buyer termination right if consent is not obtained."
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "Make delivery of releases a completion deliverable; do not rely on a post-Completion release promise."
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "Require the Seller to fund or pay the bonuses and on-costs at or before Completion"
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "Seek a specific indemnity covering loss from failure to obtain the rights or claims relating to the work"
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "Seek a specific indemnity for losses, claims, notification, remediation and regulatory response arising from the incident"
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PARTIAL",
      "evidence": "The three renewals total **AUD 330,000**, but the disclosures do not establish whether they are terminable, accrued, unavoidable or ordinary-course."
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "Specific indemnities, covenants and purchase-price adjustments should not be swallowed by the general cap or basket."
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "The share register at DD-012 is a source of evidence, not a substitute for SPA title protections or completion mechanics."
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "Seek tailored tax and IP warranties, appropriate disclosure and remedies."
    }
  ],
  "adopts_framing": false,
  "adopts_framing_evidence": "",
  "names_manipulation": false
}

